411	    private Object reviewDedupOrNull(String requestId) {
412	        List<Map<String, Object>> rows = jdbc.queryForList(
413	                "SELECT request_id FROM request_dedup WHERE request_id = ?", requestId);
414	        return rows.isEmpty() ? null : rows.get(0);
415	    }
416	
